package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.documental.*;import cl.nexbyte.siger.institucional.robustez.FalloTecnico;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.io.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
class VersionesDocumentalesTest {
 @TempDir Path temp;DocumentosReqFixture x;DocumentosGestion casos;VersionesDocumentales v;
 @BeforeEach void setup()throws Exception{x=new DocumentosReqFixture(temp,null,"_docmeta");casos=new DocumentosGestion(x.d.db,x.files,new AutorizacionNucleo(x.f.core),p->true,x.inspector,x.clock);v=new VersionesDocumentales(x.d.db,x.f.core,x.f.cat,casos,x.docs,x.clock);}
 @AfterEach void close()throws Exception{if(x!=null)x.close();}
 long count(String table){return x.d.db.sql.queryForObject("SELECT COUNT(*) FROM "+table,Long.class);}
 void denied(int code,Runnable op){assertEquals(code,assertThrows(FalloTecnico.class,op::run).status);}
 VersionesDocumentales.Vista ver(UUID d){return v.ver(x.f.a(x.f.profA),"REQ",x.req,d);}
 VersionesDocumentales.Vista declarar(UUID d){return v.registrar(x.f.a(x.f.profA),x.key(),"REQ",x.req,d,new VersionesDocumentales.Metadatos(-1,"Título declarado sintético","Tipo declarado sintético","Declaración expresa del responsable"));}
 UUID doc(){return x.cargar().id();}
 @Test void documentoNoRecibeFaseNiNumeroPorInferencia(){UUID d=doc();var m=ver(d);assertFalse(m.acreditada());assertEquals(-1,m.revision());assertNull(m.numero());assertNull(m.titulo());assertEquals("SIN_ACREDITAR",m.fase());assertEquals(0,count("management_document_metadata"));assertTrue(m.editable());}
 @Test void rectificacionConservaMetadatosPreviosOriginalYAutorDeCadaCambio()throws Exception{
  UUID d=doc();var before=x.d.db.sql.queryForMap("SELECT * FROM institution_document WHERE id=?",d.toString());declarar(d);
  v.registrar(x.f.a(x.f.headA),x.key(),"REQ",x.req,d,new VersionesDocumentales.Metadatos(0,"Título corregido","Informe declarado","Corrección fundada de metadatos"));var m=ver(d);assertEquals(1,m.revision());assertEquals(2,m.historial().size());assertEquals(x.f.profA,m.historial().getLast().autor());assertEquals(x.f.headA,m.historial().getFirst().autor());assertEquals("Título declarado sintético",m.historial().getLast().datos().get("title_text"));assertEquals(before,x.d.db.sql.queryForMap("SELECT * FROM institution_document WHERE id=?",d.toString()));assertArrayEquals(x.bytes().readAllBytes(),Files.readAllBytes(x.docs.verificarArchivo(x.docs.referencia(x.f.a(x.f.profA),x.req,d,"CONTENIDO"))));
 }
 @Test void finalConservaFechaAutorYBytesInclusoConRectificacionPosterior(){
  UUID d=doc();declarar(d);var finished=v.finalizar(x.f.a(x.f.profA),x.key(),"REQ",x.req,d,new VersionesDocumentales.Finalizar(0,"Referencia externa declarada, no firma acreditada","Versión final declarada por responsable"));assertEquals("FINAL",finished.fase());assertEquals(x.clock.instant(),finished.finalDeclaradoEn());assertEquals(x.f.profA,finished.declaradoPor());
  denied(409,()->v.finalizar(x.f.a(x.f.headA),x.key(),"REQ",x.req,d,new VersionesDocumentales.Finalizar(1,null,"No finaliza dos veces")));
  var corrected=v.registrar(x.f.a(x.f.headA),x.key(),"REQ",x.req,d,new VersionesDocumentales.Metadatos(1,"Corrección descriptiva","Tipo corregido","No reemplaza la versión final"));assertEquals("FINAL",corrected.fase());assertEquals(finished.finalDeclaradoEn(),corrected.finalDeclaradoEn());assertEquals(finished.declaradoPor(),corrected.declaradoPor());assertEquals(1,count("institution_document"));
 }
 @Test void sucesoraEsOtroOriginalYConservaFinalAnteriorSinCasoNiGestionNueva(){
  UUID a=doc(),b=doc();declarar(a);declarar(b);v.finalizar(x.f.a(x.f.profA),x.key(),"REQ",x.req,a,new VersionesDocumentales.Finalizar(0,null,"Primera versión final"));long cases=count("core_case"),acts=count("institution_req_action");
  var next=v.suceder(x.f.a(x.f.profA),x.key(),"REQ",x.req,b,new VersionesDocumentales.Sucesor(0,1,a,"Nueva versión preservando su antecedente"));assertEquals(2,next.numero());assertEquals(a,next.anterior());assertEquals("BORRADOR",next.fase());assertEquals("FINAL",ver(a).fase());assertEquals(b,ver(a).siguiente());assertEquals(2,count("institution_document"));assertEquals(cases,count("core_case"));assertEquals(acts,count("institution_req_action"));
 }
 @Test void reintentosConservanComandoEHistoriaYNoReabrenFinalTrasCierre(){
  UUID d=doc(),key=x.key();var r=new VersionesDocumentales.Metadatos(-1,"Declarado","Tipo","Fundamento sintético");v.registrar(x.f.a(x.f.profA),key,"REQ",x.req,d,r);v.registrar(x.f.a(x.f.profA),key,"REQ",x.req,d,r);assertEquals(1,count("management_document_metadata_command"));assertEquals(1,ver(d).historial().size());
  denied(409,()->v.registrar(x.f.a(x.f.profA),key,"REQ",x.req,d,new VersionesDocumentales.Metadatos(-1,"Otro","Tipo","Cambio con misma clave")));
  UUID finalKey=x.key();var f=new VersionesDocumentales.Finalizar(0,null,"Conclusión del documento");v.finalizar(x.f.a(x.f.profA),finalKey,"REQ",x.req,d,f);x.f.core.u2().actuar(x.f.a(x.f.headA),x.key(),x.req,new ContratosNucleo.Decision(x.revision(),"Cierre explícito"),true);assertEquals("FINAL",v.finalizar(x.f.a(x.f.profA),finalKey,"REQ",x.req,d,f).fase());assertEquals(2,ver(d).historial().size());
 }
 @Test void versionObsoletaOtroReqTiYOtraAreaNoRectifican(){UUID d=doc();declarar(d);for(String actor:List.of(x.f.ti,x.f.profB,x.f.headB,x.f.dist))denied(404,()->v.ver(x.f.a(actor),"REQ",x.req,d));denied(409,()->v.registrar(x.f.a(x.f.profA),x.key(),"REQ",x.req,d,new VersionesDocumentales.Metadatos(-1,"Cambio","Tipo","Versión obsoleta")));UUID other=x.nuevoReq();denied(404,()->v.ver(x.f.a(x.f.profA),"REQ",other,d));assertEquals(1,ver(d).historial().size());}
 @Test void firNoSeConvierteEnVersionOrdinariaPorEnlazar(){UUID a=doc(),b=doc();declarar(a);declarar(b);x.docs.proteger(x.f.a(x.f.headA),x.key(),x.req,a,new DocumentosRequerimiento.Proteccion(0,"FIR","Protección específica del antecedente"));denied(409,()->v.suceder(x.f.a(x.f.profA),x.key(),"REQ",x.req,b,new VersionesDocumentales.Sucesor(0,0,a,"No hereda ni rebaja reserva")));x.docs.proteger(x.f.a(x.f.headA),x.key(),x.req,b,new DocumentosRequerimiento.Proteccion(0,"FIR","Protección explícita de la sucesora"));assertEquals(2,v.suceder(x.f.a(x.f.profA),x.key(),"REQ",x.req,b,new VersionesDocumentales.Sucesor(0,0,a,"Sucesión con protección expresa equivalente")).numero());assertEquals("FIR",x.docs.documento(x.f.a(x.f.profA),x.req,b).proteccion());}
 @Test void dosSucesorasConcurrentesConservanUnaSolaCadenaSinPerderOriginales()throws Exception{
  UUID a=doc(),b=doc(),c=doc();for(UUID d:List.of(a,b,c))declarar(d);var go=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var futures=new ArrayList<Future<Boolean>>();for(UUID d:List.of(b,c))futures.add(pool.submit(()->{go.await();try{v.suceder(x.f.a(x.f.profA),x.key(),"REQ",x.req,d,new VersionesDocumentales.Sucesor(0,0,a,"Una sucesora por versión"));return true;}catch(FalloTecnico e){assertEquals(409,e.status);return false;}}));go.countDown();assertNotEquals(futures.get(0).get(8,TimeUnit.SECONDS),futures.get(1).get(8,TimeUnit.SECONDS));}assertEquals(1,count("management_document_successor"));assertEquals(3,count("institution_document"));assertEquals(1,ver(a).revision());
 }
 @Test void cicloYRamaSeRechazanSinModificarFases(){UUID a=doc(),b=doc(),c=doc();for(UUID d:List.of(a,b,c))declarar(d);v.suceder(x.f.a(x.f.profA),x.key(),"REQ",x.req,b,new VersionesDocumentales.Sucesor(0,0,a,"A hacia B"));denied(409,()->v.suceder(x.f.a(x.f.profA),x.key(),"REQ",x.req,a,new VersionesDocumentales.Sucesor(1,1,b,"No cerrar ciclo")));denied(409,()->v.suceder(x.f.a(x.f.profA),x.key(),"REQ",x.req,c,new VersionesDocumentales.Sucesor(0,1,a,"No crear segunda rama")));assertEquals(1,count("management_document_successor"));}
 @Test void revocacionConOperadorAnteriorCierraMetadatosHistoriaYEscritura(){UUID d=doc();declarar(d);var a=x.f.a(x.f.profA);x.clock.avanzar(1801);denied(403,()->v.ver(a,"REQ",x.req,d));denied(403,()->v.registrar(a,x.key(),"REQ",x.req,d,new VersionesDocumentales.Metadatos(0,"No escribir","Tipo","No conserva acceso por autoría")));assertEquals(1,count("management_document_metadata_history"));}
 @Test void falloTransaccionalNoDejaDeclaracionNiComandoParciales(){
  UUID d=doc();x.d.ddl(sql->sql.execute("ALTER TABLE management_document_metadata_history ADD CONSTRAINT docmeta_rollback CHECK(revision=99)"));try{var e=assertThrows(org.springframework.dao.DataAccessException.class,()->declarar(d));assertTrue(org.springframework.core.NestedExceptionUtils.getMostSpecificCause(e).getMessage().toLowerCase(Locale.ROOT).contains("docmeta_rollback"));}finally{x.d.ddl(sql->sql.execute("ALTER TABLE management_document_metadata_history DROP "+(System.getProperty("siger.test.autoridad.mysql")==null?"CONSTRAINT":"CHECK")+" docmeta_rollback"));}assertEquals(0,count("management_document_metadata"));assertEquals(0,count("management_document_metadata_history"));assertEquals(0,count("management_document_metadata_command"));assertEquals(1,count("institution_document"));
 }
 @Test void colaboradorLeeSoloMetadatosDeDocumentoPermitidoSinHistoriaNiSucesorFir(){
  UUID c=x.abrir();x.f.otorgar(x.f.profB,"PROFESIONAL","AREA_A");x.f.core.equipo().incorporar(x.f.a(x.f.profA),x.key(),c,new EquipoCaso.Incorporar(0,x.f.profB,"Colaboración local acreditada"));UUID a=casos.cargar(x.f.a(x.f.profA),x.key(),c,null,"base.txt",x.bytes()).id(),b=casos.cargar(x.f.a(x.f.profA),x.key(),c,null,"nueva.txt",x.bytes()).id();
  for(UUID d:List.of(a,b)){x.f.core.contenidos().proteger(x.f.a(x.f.headA),x.key(),c,d,new ContenidoInstitucional.Proteccion(0,"ORDINARIO","Consulta ordinaria de equipo"));v.registrar(x.f.a(x.f.profA),x.key(),"CASO",c,d,new VersionesDocumentales.Metadatos(-1,"Título","Tipo","Declaración explícita de Caso"));}
  v.suceder(x.f.a(x.f.profA),x.key(),"CASO",c,b,new VersionesDocumentales.Sucesor(0,0,a,"Sucesora de Caso"));x.f.core.contenidos().proteger(x.f.a(x.f.headA),x.key(),c,b,new ContenidoInstitucional.Proteccion(1,"FIR","Reserva posterior específica"));var lectura=v.ver(x.f.a(x.f.profB),"CASO",c,a);assertFalse(lectura.editable());assertTrue(lectura.historial().isEmpty());assertNull(lectura.siguiente());denied(404,()->v.ver(x.f.a(x.f.profB),"CASO",c,b));denied(404,()->v.registrar(x.f.a(x.f.profB),x.key(),"CASO",c,a,new VersionesDocumentales.Metadatos(1,"No edita","Tipo","Colaboración no equivale a responsabilidad")));
 }
 @Test void cuentaAliasNoHeredaResponsabilidadParaDeclararVersiones()throws Exception{
  UUID d=doc();declarar(d);String alias=x.f.user("alias.versiones");var r=x.d.mapper.readValue(Base64.getDecoder().decode(x.d.db.sql.queryForObject("SELECT signed_payload FROM authority_batch ORDER BY revision DESC LIMIT 1",String.class)),cl.nexbyte.siger.institucional.identidad.AutoridadesInstitucionales.Registro11.class);var bindings=new ArrayList<>(r.vinculos());bindings.add(new cl.nexbyte.siger.institucional.identidad.AutoridadesInstitucionales.Vinculo(alias,"p-"+x.f.profA,x.f.start,x.f.end,ConcesionFixture.huella(x.d.db,alias)));
  x.f.importar(new cl.nexbyte.siger.institucional.identidad.AutoridadesInstitucionales.Registro11("1.1",r.revision()+1,x.clock.instant(),r.expira(),bindings,r.mandatos(),r.areas(),r.ambitos(),r.cambiosArea()));x.f.otorgar(alias,"PROFESIONAL","AREA_A");denied(404,()->v.ver(x.f.a(alias),"REQ",x.req,d));denied(404,()->v.registrar(x.f.a(alias),x.key(),"REQ",x.req,d,new VersionesDocumentales.Metadatos(0,"No edita otra cuenta","Tipo","Misma persona sin asignación de esta cuenta")));assertEquals(1,ver(d).historial().size());
 }
 @Test void documentoHistoricoNoAcreditadoNoOfreceDeclaracionPorAtajo(){
  UUID c=x.abrir();UUID d=casos.cargar(x.f.a(x.f.profA),x.key(),c,null,"sin-acreditacion.txt",x.bytes()).id();x.d.db.sql.update("DELETE FROM document_content_policy WHERE document_id=?",d.toString());var view=v.ver(x.f.a(x.f.profA),"CASO",c,d);assertFalse(view.acreditada());assertFalse(view.editable());
  denied(409,()->v.registrar(x.f.a(x.f.profA),x.key(),"CASO",c,d,new VersionesDocumentales.Metadatos(-1,"No regulariza por versión","Tipo","Requiere acreditar propietario y protección")));assertEquals(0,count("management_document_metadata"));
 }
 @Test void cierreRetiraFacultadDeFinalizarPeroConservaRectificacionDescriptiva(){UUID d=doc();declarar(d);var before=x.d.db.sql.queryForMap("SELECT * FROM institution_document WHERE id=?",d.toString());x.f.core.u2().actuar(x.f.a(x.f.headA),x.key(),x.req,new ContratosNucleo.Decision(x.revision(),"Cierre explícito"),true);var read=ver(d);assertTrue(read.editable());assertFalse(read.finalizable());assertFalse(read.permiteSucesion());denied(409,()->v.finalizar(x.f.a(x.f.profA),x.key(),"REQ",x.req,d,new VersionesDocumentales.Finalizar(0,null,"No es finalización poscierre")));v.registrar(x.f.a(x.f.headA),x.key(),"REQ",x.req,d,new VersionesDocumentales.Metadatos(0,"Descripción rectificada","Tipo declarado","Corrección descriptiva sin nueva gestión"));assertEquals("BORRADOR",ver(d).fase());assertEquals(before,x.d.db.sql.queryForMap("SELECT * FROM institution_document WHERE id=?",d.toString()));}
}
